-- The eras map (12 October): the plot is the centred 24x24 cells of the 30-cell square (cells 3..26). Buildings that
-- stood in the outer ring move inside (clamped by their footprint); obstacles out there are simply gone (they respawn).
UPDATE buildings SET grid_x = GREATEST(3, LEAST(grid_x, 27 - CASE
    WHEN rotation % 180 = 0 THEN CASE type WHEN 'PITCH' THEN 8 WHEN 'TRAINING_CENTER' THEN 6 WHEN 'ACADEMY' THEN 5 WHEN 'TICKET_OFFICE' THEN 5 WHEN 'PARKING' THEN 5
        WHEN 'MEDICAL_CENTER' THEN 4 WHEN 'CLUB_SHOP' THEN 4 WHEN 'MUSEUM' THEN 4 WHEN 'CAFE' THEN 3 WHEN 'BASKETBALL_COURT' THEN 3 WHEN 'TENNIS_COURT' THEN 3 ELSE 1 END
    ELSE CASE type WHEN 'PITCH' THEN 6 WHEN 'TRAINING_CENTER' THEN 4 WHEN 'ACADEMY' THEN 4 WHEN 'TICKET_OFFICE' THEN 2 WHEN 'PARKING' THEN 3
        WHEN 'MEDICAL_CENTER' THEN 4 WHEN 'CLUB_SHOP' THEN 3 WHEN 'MUSEUM' THEN 5 WHEN 'CAFE' THEN 3 WHEN 'BASKETBALL_COURT' THEN 2 WHEN 'TENNIS_COURT' THEN 2 ELSE 1 END END)),
    grid_y = GREATEST(3, LEAST(grid_y, 27 - CASE
    WHEN rotation % 180 = 0 THEN CASE type WHEN 'PITCH' THEN 6 WHEN 'TRAINING_CENTER' THEN 4 WHEN 'ACADEMY' THEN 4 WHEN 'TICKET_OFFICE' THEN 2 WHEN 'PARKING' THEN 3
        WHEN 'MEDICAL_CENTER' THEN 4 WHEN 'CLUB_SHOP' THEN 3 WHEN 'MUSEUM' THEN 5 WHEN 'CAFE' THEN 3 WHEN 'BASKETBALL_COURT' THEN 2 WHEN 'TENNIS_COURT' THEN 2 ELSE 1 END
    ELSE CASE type WHEN 'PITCH' THEN 8 WHEN 'TRAINING_CENTER' THEN 6 WHEN 'ACADEMY' THEN 5 WHEN 'TICKET_OFFICE' THEN 5 WHEN 'PARKING' THEN 5
        WHEN 'MEDICAL_CENTER' THEN 4 WHEN 'CLUB_SHOP' THEN 4 WHEN 'MUSEUM' THEN 4 WHEN 'CAFE' THEN 3 WHEN 'BASKETBALL_COURT' THEN 3 WHEN 'TENNIS_COURT' THEN 3 ELSE 1 END END));
DELETE FROM obstacles WHERE grid_x < 3 OR grid_y < 3 OR grid_x > 25 OR grid_y > 25;
